                        var url = window.wv.getMap("v..$browserChangeUrl");

                        if(isAnon && !document.querySelector("#aaaa")) document.head.innerHTML += `<style id="aaaa">.x78zum5.xdt5ytf.x1iyjqo2.xl56j7k.xyzq4qe.xtdtrs8.xixxii4.xh8yej3 { display: none !important; }</style>`;
